-- ============================================================================
-- B5 FOLLOW-ON W4 PART B (typed "your case" panel modes): network.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (b), and decision D2 (a panel may reach the capstone case when the
-- learner types it; no panel DEFAULT state lands on a graded answer). Owner
-- approved D1 to D7 as recommended, 2026-09-21. The panels ship with the
-- NextGen zip; this file adds one sentence to each brief saying where the case
-- can be typed.
--
-- INTERMEDIATE (6 graded field(s) now read in a typed panel mode:
-- net_bypass_mass_lbd, net_crosslink_mass_lbd, net_header_h1_psia,
-- net_satellite_m_psia, net_tee_h2_psia, net_trunk_mass_lbd)
--   POINTER appended: On the course panel, the Network explorer's "Your network,
--   typed and solved" view solves this field as you type it (the separator, the
--   five wells with their flowlines, the allocation and the capacity limit, and
--   the four branches in their drawn sense) and prints every node pressure and
--   branch mass to six decimals.
-- ADVANCED (5 graded field(s) now read in a typed panel mode:
-- fight_w1_rate_lbd, fight_w4_rate_lbd, hidden_gap_fraction,
-- hidden_produced_lbd, stream_bypass_water_stbd)
--   POINTER appended: On the course panel, the Fight explorer's "Your network,
--   typed, and what its solve hides" view solves this field as you type it,
--   wells in the order above, with each well's tested split and linear
--   conductances, and prints the rates on the system, the stream on every
--   branch, the linearised twin, and the conservation check to at least the
--   precision graded here.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently and no attempts guard is needed.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W4
-- text (left alone). Anything else raises and the file rolls back. A file that
-- will write first checks the W1 post-state and refuses without it. Generated
-- by docs/graded-field-audit/w4b_capstones.py from w4b/network.json. SAFE TO
-- RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- network / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'network' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w4b network refused: network/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'ce62a20519a1f6e4ee0d774e8cd5d51a' and fields = '[{"key": "net_header_h1_psia", "tol": 0.00044, "unit": "psia", "label": "West manifold pressure", "expected": 879.9476730307991}, {"key": "net_satellite_m_psia", "tol": 0.00045, "unit": "psia", "label": "Satellite tee pressure", "expected": 884.148272605056}, {"key": "net_tee_h2_psia", "tol": 0.00036, "unit": "psia", "label": "Trunk tee pressure", "expected": 704.6819057375309}, {"key": "net_trunk_mass_lbd", "tol": 0.0089, "unit": "lb/d", "label": "Mass the trunk carries", "expected": 17662.798867634527}, {"key": "net_bypass_mass_lbd", "tol": 0.0065, "unit": "lb/d", "label": "Mass the west bypass carries", "expected": 12974.021847848679}, {"key": "net_crosslink_mass_lbd", "tol": 0.00048, "unit": "lb/d", "label": "Mass on the crosslink, drawn sense", "expected": -942.7867573914898}]'::jsonb then 'old'
              when md5(prompt) = '97136cc8948a2f49e256b9032274a801' and fields = '[{"key": "net_header_h1_psia", "tol": 0.00044, "unit": "psia", "label": "West manifold pressure", "expected": 879.9476730307991}, {"key": "net_satellite_m_psia", "tol": 0.00045, "unit": "psia", "label": "Satellite tee pressure", "expected": 884.148272605056}, {"key": "net_tee_h2_psia", "tol": 0.00036, "unit": "psia", "label": "Trunk tee pressure", "expected": 704.6819057375309}, {"key": "net_trunk_mass_lbd", "tol": 0.0089, "unit": "lb/d", "label": "Mass the trunk carries", "expected": 17662.798867634527}, {"key": "net_bypass_mass_lbd", "tol": 0.0065, "unit": "lb/d", "label": "Mass the west bypass carries", "expected": 12974.021847848679}, {"key": "net_crosslink_mass_lbd", "tol": 0.00048, "unit": "lb/d", "label": "Mass on the crosslink, drawn sense", "expected": -942.7867573914898}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'network' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w4b network refused: network/intermediate matches neither its published form (prompt md5 ce62a20519a1f6e4ee0d774e8cd5d51a) nor its W4 form (prompt md5 97136cc8948a2f49e256b9032274a801), with the fields this file was generated against';
  end if;

  -- network / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'network' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w4b network refused: network/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '9d0efffe22ebb0f45ff8484e8f71d4d3' and fields = '[{"key": "fight_w1_rate_lbd", "tol": 0.0031, "unit": "lb/d", "label": "OBIAFU-3 rate on the system", "expected": 6161.276989112374}, {"key": "fight_w4_rate_lbd", "tol": 0.00037, "unit": "lb/d", "label": "OBIAFU-14 rate on the system", "expected": 729.3706808145245}, {"key": "stream_bypass_water_stbd", "tol": 0.00074, "unit": "stb/d", "label": "Water on the west bypass", "expected": 1470.97340763847}, {"key": "exact_linear_h1_psia", "tol": 0.00032, "unit": "psia", "label": "Linearised twin west manifold pressure", "expected": 626.3272410560802}, {"key": "hidden_produced_lbd", "tol": 0.009, "unit": "lb/d", "label": "Produced, as the conservation check reports it", "expected": 17962.798867634523}, {"key": "hidden_gap_fraction", "tol": 8.4E-9, "unit": "dimensionless", "label": "Relative conservation gap", "expected": 0.01670118349655065}]'::jsonb then 'old'
              when md5(prompt) = '8ae804be9a3c904fe93b2488ba0bee1b' and fields = '[{"key": "fight_w1_rate_lbd", "tol": 0.0031, "unit": "lb/d", "label": "OBIAFU-3 rate on the system", "expected": 6161.276989112374}, {"key": "fight_w4_rate_lbd", "tol": 0.00037, "unit": "lb/d", "label": "OBIAFU-14 rate on the system", "expected": 729.3706808145245}, {"key": "stream_bypass_water_stbd", "tol": 0.00074, "unit": "stb/d", "label": "Water on the west bypass", "expected": 1470.97340763847}, {"key": "exact_linear_h1_psia", "tol": 0.00032, "unit": "psia", "label": "Linearised twin west manifold pressure", "expected": 626.3272410560802}, {"key": "hidden_produced_lbd", "tol": 0.009, "unit": "lb/d", "label": "Produced, as the conservation check reports it", "expected": 17962.798867634523}, {"key": "hidden_gap_fraction", "tol": 8.4E-9, "unit": "dimensionless", "label": "Relative conservation gap", "expected": 0.01670118349655065}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'network' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w4b network refused: network/advanced matches neither its published form (prompt md5 9d0efffe22ebb0f45ff8484e8f71d4d3) nor its W4 form (prompt md5 8ae804be9a3c904fe93b2488ba0bee1b), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W4 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w4b network: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its post-state is this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'advanced' and c.active and f->>'key' = 'a111_ddi')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                     where c.app_slug = 'petrophysics' and c.tier = 'advanced' and c.active and f->>'key' = 'rw_arps'
                       and (f->>'tol')::float8 = 0.00005) then
    raise exception 'w4b network refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values that only exist once the whole of OBIAFU SOUTH is solved at once. THE SAME FIELD, restated in full so nothing has to be carried across from another tier. THE DELIVERY BOUNDARY is a separator held at 235 PSIA, and it is the only node on the system whose pressure is known. THE FIVE WELLS, as Vogel inflows in LB/D at a reservoir pressure in PSIA: OBIAFU-3 is 7,300 at 3,250; OBIAFU-7 is 5,400 at 2,050; OBIAFU-11 is 6,900 at 2,950; OBIAFU-14 is 1,850 at 1,180. Vogel is q equals qmax times one less 0.2 x less 0.8 x squared with x the wellhead over the reservoir pressure clipped into zero to one. THE FIFTH WELL IS DIFFERENT AND IT IS THE REASON THIS FIELD IS WORTH SOLVING: OBIAFU-19 is a Vogel inflow of 2,640 LB/D at 1,900 PSIA that is HELD TO A FACILITY ALLOCATION of 1,450 LB/D, so what it delivers is the SMALLER of that allocation and its Vogel curve, and its flowline is CAPACITY LIMITED at 1,150 LB/D in either direction. THE TOPOLOGY. There is a WEST MANIFOLD, a SATELLITE TEE, a TRUNK TEE and the separator. OBIAFU-3, OBIAFU-7, OBIAFU-14 and OBIAFU-19 each run their own flowline into the WEST MANIFOLD, at conductances of 430, 505, 232 and 210 LB/D PER ROOT PSI respectively. OBIAFU-11 runs its own flowline into the SATELLITE TEE at 390. A WEST BYPASS runs from the west manifold to the trunk tee at 980. A CROSSLINK is DRAWN from the west manifold to the satellite tee at 460. A SATELLITE LOOP LEG runs from the satellite tee to the trunk tee at 350. And the TRUNK runs from the trunk tee to the separator at 815. Every branch obeys q equals k times the sign of the pressure difference times the square root of its magnitude, signed from the branch''s drawn start to its drawn end. Nine branches, eight unknown pressures, one loop. Solve it to a tolerance of 1e-12 with the iteration cap left at the module default. Report: (1) the WEST MANIFOLD PRESSURE; (2) the SATELLITE TEE PRESSURE; (3) the TRUNK TEE PRESSURE; (4) the MASS THE TRUNK CARRIES; (5) the MASS THE WEST BYPASS CARRIES; and (6) the MASS ON THE CROSSLINK, SIGNED IN THE DRAWN SENSE from the west manifold to the satellite tee. Traps. A DRAWN ARROW IS NOT A FLOW DIRECTION. The from and the to of a branch are a sign convention somebody chose before anybody solved anything, and the answer decides which way mass actually moves; field 6 is asked for signed in the drawn sense precisely so that a wrong sign is a wrong answer rather than a footnote. The satellite tee is fed by one well through a stiff flowline while the west manifold is fed by four through slacker ones, and where those two land relative to each other is a property of the solution and not of the drawing. Nothing may be solved against a wellhead pressure typed in by hand: that is exactly what this tier exists to replace, and a well solved against an assumed backpressure is a different and easier problem. Every well pressure is an unknown. OBIAFU-19''s inflow is the smaller of its allocation and its Vogel curve and its flowline cannot pass more than its limit in either direction, and both of those are conditions of the case rather than optional refinements. And every flow here is a MASS in lb/d: mixing a surface volume into a network balance is the mistake this module''s currency rule exists to prevent. Free checks: field 2 must come out ABOVE field 1, and that ordering is what makes field 6 NEGATIVE. Field 6 must equal minus 460 times the square root of field 2 less field 1. Field 5 must equal 980 times the square root of field 1 less field 3. Field 4 must equal 815 times the square root of field 3 less 235. Field 5 plus 350 times the square root of field 2 less field 3 must equal field 4 EXACTLY, since the trunk tee takes in the west bypass and the satellite loop leg and puts out the trunk and does nothing else. The four pressures must fall in the order field 2, field 1, field 3, then 235. The pressure difference across the crosslink, field 2 less field 1, must come out under 5 PSI while the trunk''s, field 3 less 235, is over 400: a ratio above one hundred, and that crosslink is the branch on this system closest to the cusp of its own square root relation, which is why it costs this solve more iterations than any single well costs on its own. Field 4 must land below 24,090 lb/d, the five wells'' qmax values added, because no gathering system delivers more than its wells can make against no backpressure at all. And field 4 is what the TRUNK CARRIES. Whether that is the same number as what the five wells produced is the Expert tier''s question and is not asked here. On the course panel, the Network explorer''s "Your network, typed and solved" view solves this field as you type it (the separator, the five wells with their flowlines, the allocation and the capacity limit, and the four branches in their drawn sense) and prints every node pressure and branch mass to six decimals.'
     where app_slug = 'network' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4b network refused: network/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '97136cc8948a2f49e256b9032274a801' and fields = '[{"key": "net_header_h1_psia", "tol": 0.00044, "unit": "psia", "label": "West manifold pressure", "expected": 879.9476730307991}, {"key": "net_satellite_m_psia", "tol": 0.00045, "unit": "psia", "label": "Satellite tee pressure", "expected": 884.148272605056}, {"key": "net_tee_h2_psia", "tol": 0.00036, "unit": "psia", "label": "Trunk tee pressure", "expected": 704.6819057375309}, {"key": "net_trunk_mass_lbd", "tol": 0.0089, "unit": "lb/d", "label": "Mass the trunk carries", "expected": 17662.798867634527}, {"key": "net_bypass_mass_lbd", "tol": 0.0065, "unit": "lb/d", "label": "Mass the west bypass carries", "expected": 12974.021847848679}, {"key": "net_crosslink_mass_lbd", "tol": 0.00048, "unit": "lb/d", "label": "Mass on the crosslink, drawn sense", "expected": -942.7867573914898}]'::jsonb) from public.academy_capstones where app_slug = 'network' and tier = 'intermediate' and active) is not true then
    raise exception 'w4b network refused: network/intermediate does not read back as its W4 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for OBIAFU SOUTH that are invisible from a converged answer read at face value. THE SAME FIELD AGAIN, restated in full. THE DELIVERY BOUNDARY is a separator held at 235 PSIA and it is the only node whose pressure is known. THE FIVE WELLS, as Vogel inflows in LB/D at a reservoir pressure in PSIA: OBIAFU-3 is 7,300 at 3,250; OBIAFU-7 is 5,400 at 2,050; OBIAFU-11 is 6,900 at 2,950; OBIAFU-14 is 1,850 at 1,180; and OBIAFU-19 is 2,640 at 1,900 but is HELD TO A FACILITY ALLOCATION of 1,450 LB/D, so it delivers the SMALLER of that allocation and its Vogel curve, on a flowline CAPACITY LIMITED at 1,150 LB/D in either direction. Vogel is q equals qmax times one less 0.2 x less 0.8 x squared with x the wellhead over the reservoir pressure clipped into zero to one. THE TOPOLOGY. OBIAFU-3, OBIAFU-7, OBIAFU-14 and OBIAFU-19 run their own flowlines into the WEST MANIFOLD at conductances of 430, 505, 232 and 210 LB/D PER ROOT PSI. OBIAFU-11 runs its own flowline into the SATELLITE TEE at 390. A WEST BYPASS runs from the west manifold to the TRUNK TEE at 980, a CROSSLINK is DRAWN from the west manifold to the satellite tee at 460, a SATELLITE LOOP LEG runs from the satellite tee to the trunk tee at 350, and the TRUNK runs from the trunk tee to the separator at 815. Every branch obeys q equals k times the sign of the pressure difference times the square root of its magnitude. Solve it to a tolerance of 1e-12 with the iteration cap at the module default. NEW HERE, AND IT IS THE POINT OF THE TIER. THE SURFACE SPLIT each well is tested at, in stb/d of oil, stb/d of water and Mscf/d of gas: OBIAFU-3 makes 1,420, 176 and 1,135; OBIAFU-7 makes 862, 645 and 708; OBIAFU-11 makes 1,238, 412 and 1,476; OBIAFU-14 makes 174, 523 and 97; and OBIAFU-19 makes 306, 58 and 241. Those component rates ride along with whatever mass the solve gives each well and are not solved for. ALSO NEW: A LINEARISED TWIN of the same field. Same topology, same wells at the same qmax and the same reservoir pressures, but every well inflow read as q equals qmax times one less p over pr and EVERY BRANCH given a LINEAR conductance in LB/D PER PSI: the four west flowlines at 31, 44, 19 and 23, the satellite flowline at 27, the west bypass at 88, the crosslink at 36, the satellite loop leg at 41 and the trunk at 63, in that same order, with the same separator at 235 PSIA and no allocation and no capacity limit anywhere. Report: (1) OBIAFU-3''S RATE ON THE SYSTEM, with all five wells producing; (2) OBIAFU-14''S RATE ON THE SYSTEM; (3) the WATER ON THE WEST BYPASS, propagated from the tested splits along the solved flow directions; (4) the WEST MANIFOLD PRESSURE OF THE LINEARISED TWIN, by its closed form; (5) what a conservation check on the turbulent solve reports as PRODUCED; and (6) that same check''s RELATIVE CONSERVATION GAP. Traps. Fields 1 and 2 are the rates ON THE SYSTEM and not on a flowline alone, and the difference between those two readings is the entire reason a network is solved rather than a well. Field 3 splits at the satellite tee by MASS SHARE, which is the only split that conserves anything, and the crosslink on this field RUNS BACKWARDS, so a learner who takes the drawing''s arrow at face value sends the satellite well''s water the wrong way and gets a plausible number that is wrong by more than a rounding. A stream mass rides along with the mass the SOLVE gives each well, and nothing in the module compares a stream mass with a well rate, which is why fields 5 and 6 exist at all. Field 4 is a DIFFERENT NETWORK: lb/d per psi and lb/d per root psi are not the same quantity and never compare, and the linearised twin is solved by assembling a weighted graph Laplacian and inverting it, with no iteration anywhere in it. Field 5 is what the check reports as PRODUCED, which is the sum of the REPORTED well rates and is not what the trunk delivers. Field 6 is a FRACTION and not a percentage. And the solve returns converged true on this field with a reported residual near 1e-12 lb/d: that residual is not field 6, it does not bound field 6, and taking it as a statement about the answer is the single mistake this tier exists to prevent. Free checks: field 1 must fall BELOW what OBIAFU-3 makes alone on its own flowline, which the Associate tier computes and which is not stated here, and field 2 must fall below HALF of what OBIAFU-14 makes alone. The weak well must lose the larger FRACTION of itself while the strong well is still the larger rate, and both halves of that are the finding: ranking wells by what they lose is not ranking them by what they make. Field 1 must equal the Vogel inflow of OBIAFU-3 evaluated at its own wellhead, and that wellhead must equal the west manifold pressure plus the square of field 1 over 430. Field 3 must exceed 1,402 stb/d, the water the four wells on the west manifold bring in directly, and must fall below 1,814 stb/d, the whole field''s tested water, because the satellite well''s water splits at its own tee and only part of it comes back over the crosslink. Field 4 must come out well BELOW the west manifold pressure of the turbulent system, which the Professional tier computes and which is not stated here, and it is the only answer in this capstone that needs no tolerance at all: Newton run on that same linear system returns it to the last bits a double carries, because Newton is exact on a linear system and Gaussian elimination shares no reasoning with it. Field 5 less the mass the trunk carries must equal exactly 300 LB/D, which is OBIAFU-19''s 1,450 lb/d allocation less the 1,150 lb/d its flowline can pass and nothing else, and that is production this field puts in and never takes out. Field 6 must equal that same difference divided by field 5, and must land above one per cent and below two. And the last check is the course itself: that gap in lb/d is more than thirteen orders of magnitude above the residual the solve reports about itself, on a return whose converged flag says true. On the course panel, the Fight explorer''s "Your network, typed, and what its solve hides" view solves this field as you type it, wells in the order above, with each well''s tested split and linear conductances, and prints the rates on the system, the stream on every branch, the linearised twin, and the conservation check to at least the precision graded here.'
     where app_slug = 'network' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4b network refused: network/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '8ae804be9a3c904fe93b2488ba0bee1b' and fields = '[{"key": "fight_w1_rate_lbd", "tol": 0.0031, "unit": "lb/d", "label": "OBIAFU-3 rate on the system", "expected": 6161.276989112374}, {"key": "fight_w4_rate_lbd", "tol": 0.00037, "unit": "lb/d", "label": "OBIAFU-14 rate on the system", "expected": 729.3706808145245}, {"key": "stream_bypass_water_stbd", "tol": 0.00074, "unit": "stb/d", "label": "Water on the west bypass", "expected": 1470.97340763847}, {"key": "exact_linear_h1_psia", "tol": 0.00032, "unit": "psia", "label": "Linearised twin west manifold pressure", "expected": 626.3272410560802}, {"key": "hidden_produced_lbd", "tol": 0.009, "unit": "lb/d", "label": "Produced, as the conservation check reports it", "expected": 17962.798867634523}, {"key": "hidden_gap_fraction", "tol": 8.4E-9, "unit": "dimensionless", "label": "Relative conservation gap", "expected": 0.01670118349655065}]'::jsonb) from public.academy_capstones where app_slug = 'network' and tier = 'advanced' and active) is not true then
    raise exception 'w4b network refused: network/advanced does not read back as its W4 form';
  end if;

  raise notice 'w4b network: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
